import re
import sys
from typing import Union, Dict, Any, Tuple

def validate_string_input(input_str: str, max_length: int = 100, min_length: int = 1) -> str:
    if not isinstance(input_str, str):
        raise ValueError("Input must be a string")
    if len(input_str) < min_length:
        raise ValueError(f"Input must be at least {min_length} characters long")
    if len(input_str) > max_length:
        raise ValueError(f"Input must be at most {max_length} characters long")

    dangerous_patterns = [
        r'<script[^>]*>.*?</script>',
        r'javascript:',
        r'on\w+\s*=',
        r'--',
        r';\s*drop\s+table',
        r'union\s+select',
        r'exec\s*\(',
        r'eval\s*\(',
        r'<iframe',
        r'<object',
        r'<embed',
        r'\.\./',
        r'\\x[0-9a-f]{2}',
    ]

    for pattern in dangerous_patterns:
        if re.search(pattern, input_str, re.IGNORECASE):
            raise ValueError("Input contains potentially dangerous content")

    if not re.match(r'^[a-zA-Z0-9\s\.\,\!\?\-\_\@\#\%\&\*\+\=\/]+$', input_str):
        raise ValueError("Input contains invalid characters")

    return input_str.strip()

def validate_numeric_input(input_val: Union[str, int, float], min_val: float = None, max_val: float = None) -> float:
    try:
        num = float(input_val)
    except (ValueError, TypeError):
        raise ValueError("Input must be a valid number")

    if num != num:
        raise ValueError("Input cannot be NaN")
    if num == float('inf') or num == float('-inf'):
        raise ValueError("Input cannot be infinity")

    if min_val is not None and num < min_val:
        raise ValueError(f"Number must be at least {min_val}")
    if max_val is not None and num > max_val:
        raise ValueError(f"Number must be at most {max_val}")

    return num

def sanitize_text(text: str) -> str:
    text = re.sub(r'[<>"\']', '', text)
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

def perform_safe_calculation(number: float, operation: str = "square") -> float:
    if operation == "square":
        result = number ** 2
    elif operation == "cube":
        result = number ** 3
    elif operation == "sqrt":
        if number < 0:
            raise ValueError("Cannot calculate square root of negative number")
        result = number ** 0.5
    elif operation == "double":
        result = number * 2
    elif operation == "half":
        result = number / 2
    else:
        raise ValueError(f"Unknown operation: {operation}")

    if result > 1e308:
        raise ValueError("Calculation resulted in overflow")

    return result

def process_user_data(name: str, age: Union[str, int, float], multiplier: Union[str, int, float]) -> Dict[str, Any]:
    try:
        validated_name = validate_string_input(name, max_length=50, min_length=2)
        validated_age = validate_numeric_input(age, min_val=0, max_val=150)
        validated_multiplier = validate_numeric_input(multiplier, min_val=0.01, max_val=10000)

        sanitized_name = sanitize_text(validated_name)

        age_squared = perform_safe_calculation(validated_age, "square")
        final_value = age_squared * validated_multiplier

        if final_value > 1e15:
            raise ValueError("Result too large")

        return {
            "status": "success",
            "name": sanitized_name,
            "age": validated_age,
            "age_squared": age_squared,
            "multiplier": validated_multiplier,
            "final_value": round(final_value, 4),
            "message": f"Hello {sanitized_name}, {validated_age}^2 * {validated_multiplier} = {final_value:.4f}"
        }
    except ValueError as e:
        return {"status": "error", "error": str(e)}

def get_user_input() -> Tuple[str, str, str]:
    try:
        name = input("Enter your name: ").strip()
        age = input("Enter your age: ").strip()
        multiplier = input("Enter a multiplier (0.01 to 10000): ").strip()
        return name, age, multiplier
    except EOFError:
        raise ValueError("No input provided")

def main() -> None:
    try:
        name, age, multiplier = get_user_input()
        result = process_user_data(name, age, multiplier)

        if result.get("status") == "error":
            print(f"Validation Error: {result['error']}")
            sys.exit(1)

        print("\n--- Results ---")
        for key, value in result
